local M = class("SimulateLiftInfoView",LikeOO.OOPopBase)
-- 侠客人生模拟器
M.m_uiName = "SimulateLift/SimulateLiftInfo"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true

function M:onEnter()
    self:bindUI()
    self.isShowPop = true
    self:showCloud(function()
        self:refreshUI()
    end)
end

function M:refreshUI()
    self:refreshNode()
end

function M:showCloud(callBack)
    local fivelinesOpenAnim = ResourceUtil:LoadUIGameObject("FivelinesNew/FivelinesOpenAnim", Vector3.zero, nil)
    fivelinesOpenAnim.transform:SetParent(self.m_rootView.transform, false)
    self.m_control:setOnceTimer(1.5, function()
        UIUtil.destroyObject(fivelinesOpenAnim)
        if callBack then
            callBack()
        end
    end)
end

function M:showShareNode()
    -- 官方包才有
    local isOfficialBag = false
    if SDKUtil.is_gmsdk then
        local bundleid = SDKUtil.sdk_params.applicationId or ""
        if bundleid == "com.hermes.wl" then
            -- 是官方包
            isOfficialBag = true
        end
    end
    self:setTextByLanKey("text_shareHintText", "castingSword_str_0027")
    self:setObjectVisible("img_QRcode", isOfficialBag)
    self:setObjectVisible("hintNode", (not isOfficialBag))

    local playerName = UserDataManager.user_data:getUserStatusDataByKey("name")
    self:setText("text_playerName", playerName)
    local server_name = UserDataManager.server_data:getServerName()
    self:setText("text_serverName", server_name)
    local head_node = self:findGameObject("head_node")
    local avatar = UserDataManager.user_data:getUserStatusDataByKey("avatar")
    local frame = UserDataManager.user_data:getUserStatusDataByKey("frame")
    GameUtil:setUserAvatar(head_node, {avatar = avatar, frame = frame}, false)
    self:setObjectVisible("shareNode", true)
end

function M:hideShereNode()
    self:setObjectVisible("img_QRcode", false)
    self:setObjectVisible("hintNode", false)
    self:setObjectVisible("shareNode", false)
end

-- popType 1 彩蛋， 2结局， 3战令
function M:popWindow(text, popType, newEggProgress)
    local isNewEgg = (popType == 1)
    local isNewEnd = (popType == 2)
    local isNewToken = (popType == 3)
    self:setObjectVisible("caidan_popImg", isNewEgg)
    self:setObjectVisible("jieju_popImg", isNewEnd)
    self:setObjectVisible("zhanling_popImg", isNewToken)
    if (not isNewToken) and (newEggProgress > 0) then
        local maxProgress = 0
        if isNewEnd then
            local result_allXlsxData = ConfigManager:getCfgByName("reopen_result_all")
            maxProgress = table.nums(result_allXlsxData)
        else
            maxProgress = 0
            local eventsXlsxData = ConfigManager:getCfgByName("reopen_events")
            for _, itemData in pairs(eventsXlsxData) do
                if (itemData.type2 == 0) and (itemData.type == 3) then
                    maxProgress = maxProgress + 1
                end
            end 
        end
        text = text.."\n（"..newEggProgress .. "/".. maxProgress .."）"
    end
    self:setText("text_popText", text)
    self:setObjectVisible("popNode", true)
    self.m_control:setOnceTimer(1.5,function()
        --if not self.isShowPop then
            self:setObjectVisible("popNode", false)
        --end
    end)  
end

function M:refreshNode()
    local isStart = (self.m_model.m_stage == self.m_model.m_liftStages.Start)
    local isSelectTalent = (self.m_model.m_stage == self.m_model.m_liftStages.SelectTalent)
    local isLiftLog = (self.m_model.m_stage == self.m_model.m_liftStages.LiftLog)
    local isEnd = (self.m_model.m_stage == self.m_model.m_liftStages.End)
    self:setObjectVisible("gameStartNode", isStart)
    self:setObjectVisible("selectTalentNode", isSelectTalent)
    self:setObjectVisible("showLiftNode", isLiftLog)
    self:setObjectVisible("endNode", isEnd)
    if isStart then
        self:setTextByLanKey("text_startText", "tid#ReopenDes_6")     
        self:setTextByLanKey("text_lotteryText", "simulateLeft_text_0012")
    elseif isSelectTalent then
        self:setTextByLanKey("text_infoText", "simulateLeft_text_0015", self.m_model.m_allCount)
        self:refreshSelectNode()
    elseif isLiftLog then
        self:refreshLiftLog()
    elseif isEnd then
        audio:SendEvtUI("UI_JiangHuCQ")
        local endXlsxData = ConfigManager:getCfgByName("reopen_result")
        self:setAttributeInfo()
        self:setAwardInfo()
        self:showLifePeak()
        self:showEnding(endXlsxData) 
    end
end

function M:showEnding(endXlsxData)
    if not self.m_model.endAwardInfoData then
        return
    end
    local endAwardInfoData = self.m_model.endAwardInfoData
    local endData = endAwardInfoData.ending_data
    if not endData then
        return
    end
    self:setObjectVisible("text_newRecord", endAwardInfoData.cur_score > self.m_model.m_data.max_score )
    self:setText("text_liftValue", endAwardInfoData.cur_score)
    local endValue = endData[3] or 0
    local firstEndValue = endData[1]
    local lastEndValue = endData[2]
    if firstEndValue and lastEndValue then
        local lastItemData =endXlsxData[tonumber(lastEndValue)]
        local endingValue = ""
        if firstEndValue > 0 then
            local firstItemData = endXlsxData[tonumber(firstEndValue)]
            endingValue = Language:getTextByKey(firstItemData.des).. Language:getTextByKey(lastItemData.des)
        else
            endingValue = Language:getTextByKey(lastItemData.des)
        end
        self:setText("text_endValue", endingValue)
        if endValue > 0 then
            self:popWindow(endingValue, 2, lastEndValue)
        end
    end
end

function M:showLifePeak()
    local eventXlsxData = ConfigManager:getCfgByName("reopen_events")
    for _, itemData in pairs(self.m_model.liftData) do
        local eventIds = itemData.eventIds
        for _, itemEventId in pairs(eventIds) do
            if itemEventId > 0 then
                local curEventXlsxData = eventXlsxData[itemEventId]
                if curEventXlsxData.highlight == 1 then
                    self:setText("text_gloryValue", Language:getTextByKey(curEventXlsxData.highlight_title))
                    self:setObjectVisible("text_gloryName", true)
                    return
                end
            end
        end
    end
    self:setText("text_gloryValue", Language:getTextByKey("simulateLeft_text_0058"))
end

-- isliftLogWindow 是否生涯界面(或投胎界面)
function M:setLeftInfo(isliftLogWindow)
    local tempAttrs, age, eventId, newEggProgress
    local showLiftNode
    if isliftLogWindow then
        tempAttrs, age, eventId, newEggProgress = self.m_model:getLastLifeInfo()
        self.m_control:showNewColorEggPopWindow(eventId, newEggProgress)
        showLiftNode = self:findGameObject("showLiftNode")
    else
        tempAttrs, age = self.m_model:getSelectTalentInfo()
        showLiftNode = self:findGameObject("selectTalentNode")
    end
    if not tempAttrs then
        return
    end
    local enumerationXlsxData = ConfigManager:getCfgByName("reopen_enumeration")
    local modeLuaBehaviour = UIUtil.findLuaBehaviour(showLiftNode)
    if modeLuaBehaviour then
        LuaBehaviourUtil.setTextByLanKey(modeLuaBehaviour, "text_age", "simulateLeft_text_0024", age)
        for qulityIndex = 1, 4 do
            local qulityItemData = tempAttrs[qulityIndex]
            local qulityItem = modeLuaBehaviour:FindGameObject("itemLeftNode_"..qulityIndex)   
            local qulityItemLua = UIUtil.findLuaBehaviour(qulityItem)
            local qulityXlsxData = enumerationXlsxData[tonumber(qulityItemData.id)]
            if qulityItemLua then
                local itemAttributeLevel = self.m_model:getAttributeLevel(false, qulityItemData.value)
                local levelName = self.m_model.m_qualityValues[itemAttributeLevel]
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityLevel", levelName)
                local color = self.m_model.m_qualityColourValues[itemAttributeLevel]
                local qulityLevel_text = qulityItemLua:FindText("text_qualityLevel")
                qulityLevel_text.color = Color(color[1],color[2], color[3])
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityName", Language:getTextByKey(qulityXlsxData.name))
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityValue", qulityItemData.value)
            end
        end
    end
end

function M:refreshLiftLog()
    self:setObjectVisible("text_hintText", true)
    self:setTextByLanKey("text_hintText", "simulateLeft_text_0060")
    local showLiftNode = self:findGameObject("showLiftNode")
    local showLiftNodeLuaBehaviour = UIUtil.findLuaBehaviour(showLiftNode)
    if showLiftNodeLuaBehaviour then
        LuaBehaviourUtil.setTextByLanKey(showLiftNodeLuaBehaviour, "text_autoText", "simulateLeft_text_0025")
        -- 初始化一条
        self:popInteractEvent()
        self:createLoopScroll()
    end
end

-- 自动播放
function M:autoPlayLift()
    local isAutoPlay = self.m_model.m_isAutoPlay
    self:setObjectVisible("img_autoSelectImg", isAutoPlay)
    if not isAutoPlay then
        return
    end
    local interactValue = self:addLiftLog()
    if interactValue == -2 then
        GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("simulateLeft_text_0032"), delay_close = 2})
        self:setObjectVisible("img_autoSelectImg", false)
        self:jumpLiftResult()
        return
    elseif interactValue == -1 then
        self:refreshListEvent()
    end
end

-- 自动刷新事件
function M:refreshListEvent()
    local cdTimer = ConfigManager:getCommonValueById(668) or 1
    self.m_control:setOnceTimer(cdTimer, function()
        if (not self) or (not self.m_model) then
            return
        end
        if not self.m_model.m_isAutoPlay then
            return
        end
        local interactValue = self:addLiftLog()
        if interactValue == -2 then
            GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("simulateLeft_text_0032"), delay_close = 2})
            self:setObjectVisible("img_autoSelectImg", false)
            self:jumpLiftResult()
            return
        elseif interactValue == -1 then
            self:refreshListEvent()
        end
    end)
end

-- 自动播放 增加一条生涯数据
function M:addLiftLog()
    local interactValue = self:popInteractEvent()
    if interactValue == -1 then
        self:createLoopScroll()
        self.m_control:detectionLifeParams()
    end
    return interactValue
end

function M:createLoopScroll()
    self:setLeftInfo(true)
    local data = self.m_model.liftData
    -- 只空出了位置，需要自己改框大小
    local all_cell_size = self:getAllItemHeight(data)
    if self.m_scroll_view == nil then
        local loopscroll = self:findGameObject("loopscroll")
        local params ={
            show_data = data,
            loop_scroll_object = loopscroll,
            update_cell =function(index, cell_obj, cell_data)
                self:refreshItem(cell_obj, cell_data, index)
            end,
            click_func = function(index, cell_object, cell_data, click_object, click_name) -- 点击回调
                if click_name == "btn_itemBg" then
                   self:refreshItemLiftList()
                end
            end,
            all_cell_size = all_cell_size
        }
        self.m_scroll_view = LoopScrollViewUtil.new(params)
    else
        self.m_scroll_view:reloadData(data,true, all_cell_size)
    end
    self.m_scroll_view:moveToCellIndex(#data)
end

-- 手动点击 增加一条生涯
function M:refreshItemLiftList()
    self.m_model:closeAutoPlay()
    self:setObjectVisible("img_autoSelectImg", self.m_model.m_isAutoPlay)
    local interactValue = self:popInteractEvent()
    if interactValue == -2 then
       self:jumpLiftResult()
        return
    elseif interactValue == -1 then
        self:createLoopScroll()
        self.m_control:detectionLifeParams()
        
    end
end

-- 互动型事件
function M:popInteractEvent()
    local interactValue,serverIndex = self.m_model:modeifyLiftData()
    if interactValue > 0 then
        -- 互动
        self.m_control:popInteractEvent(interactValue, serverIndex)
    end
    return interactValue
end

function M:jumpLiftResult()
    local isCanJumpResult = self.m_model.m_isCanJumpResult
    if not isCanJumpResult then
        self.m_model:setCanJumpResult(true)
        self.m_control:detectionLifeParams(true)
        self:setObjectVisible("btn_jumpEnd", true)
        self:setObjectVisible("text_hintText", false)
    else
        self.m_control:jumpLiftResult()
    end
end

-- 获取所有内容宽度高度
function M:getAllItemHeight(data)
    local allCounts = {}
    for index = 1, table.nums(data) do
        local itemData = data[index]
        local contentInfo = itemData.contents
        local lineCount = 0
        for i = 1, table.nums(contentInfo) do
            local contentInfoItem = contentInfo[i]
            local liftItemData = contentInfoItem.content
            local liftItemDataCount = table.nums(string.cutText(liftItemData))
            -- 一行24个字
            local curLineCount = math.ceil(liftItemDataCount / 24) 
            lineCount = lineCount + curLineCount
        end
        local scaleValue = (lineCount <= 3) and Vector2(658, 95) or Vector2(658, 95 + (lineCount - 3) * 25)
        table.insert(allCounts, scaleValue)
    end
    return allCounts
end

-- 非自动刷新
function M:notAutoRefshList()
    self.m_model:closeAutoPlay()
    self:setObjectVisible("img_autoSelectImg", self.m_model.m_isAutoPlay)
    local interactValue = self:addLiftLog()
    if interactValue == -2 then
        GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("simulateLeft_text_0032"), delay_close = 2})
        self:setObjectVisible("img_autoSelectImg", false)
        self:jumpLiftResult()
        return
    end
end

function M:refreshItem(cell_obj, cell_data, index)
    local luaBehaviour = UIUtil.findLuaBehaviour(cell_obj)
    if luaBehaviour then
        -- 格式{年龄，{该年龄的第几条，服务器内容Index，内容}, {该年龄的第几条，服务器内容Index，内容}}
        --{ageIndex = ageIndex, serverIndex = index, content = serverContent, attrs = attrs})
        local age = cell_data.age or ""
        --local roleId = cell_data.roleId
        local contentInfo = cell_data.contents or {}
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_ageText","simulateLeft_text_0024",age)
        local content = ""
        local lineCount = 0
        local contentCount = table.nums(contentInfo)
        for i = 1, contentCount do
            local contentInfoItem = contentInfo[i]
            local liftItemData = contentInfoItem.content
            content = content .. liftItemData .. "\n"
            local liftItemDataCount = table.nums(string.cutText(liftItemData))
            -- 一行24个字
            local curLineCount = math.ceil(liftItemDataCount / 24)
            lineCount = lineCount + curLineCount
        end
        LuaBehaviourUtil.setText(luaBehaviour, "text_contentText", content)
        local text_contentTextTrans = luaBehaviour:FindRectTransform("text_contentText")
        text_contentTextTrans.sizeDelta = (lineCount <= 3) and Vector2(547, 74) or Vector2(547, 74 + (lineCount -3) * 26)
        
        local cellTrans = luaBehaviour:FindRectTransform("cell")
        cellTrans.sizeDelta = (lineCount <= 3) and Vector2(658, 95) or Vector2(658, 95 + (lineCount - 3) * 25)
    end
end

function M:setAttributeInfo()
    local enumerationXlsxData = ConfigManager:getCfgByName("reopen_enumeration")
    local tempAttrs, age = self.m_model:getLastLifeInfo()
    if not tempAttrs then
        return
    end
    local endNode = self:findGameObject("endNode")
    local endNodeLuaBehaviour = UIUtil.findLuaBehaviour(endNode)
    self:setTextByLanKey("text_ageValue", "simulateLeft_text_0024", age)
    if endNodeLuaBehaviour then
        local maxValues = ConfigManager:getCommonValueById(674) or {}
        for qulityIndex = 1, 4 do
            local qulityItemData = tempAttrs[qulityIndex]
            local qulityItem = endNodeLuaBehaviour:FindGameObject("itemNode_"..qulityIndex)
            local qulityItemLua = UIUtil.findLuaBehaviour(qulityItem)
            local qulityXlsxData = enumerationXlsxData[tonumber(qulityItemData.id)]
            if qulityItemLua then
                local itemValue = qulityItemData.value
                local maxValue = maxValues[qulityIndex] or 1
                local itemAttributeLevel = self.m_model:getAttributeLevel(true, itemValue)
                local levelName = self.m_model.m_qualityValues[itemAttributeLevel]
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityLevel", levelName)
                local color = self.m_model.m_qualityColourValues[itemAttributeLevel]
                local qulityLevel_text = qulityItemLua:FindText("text_qualityLevel")
                qulityLevel_text.color = Color(color[1],color[2], color[3])
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityName", Language:getTextByKey(qulityXlsxData.name))
                LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityValue", itemValue)
                local slider = qulityItemLua:FindSlider("item_slider")
                slider.value = itemValue > maxValue and 1 or (itemValue / maxValue)
            end
        end
    end
end

function M:setAwardInfo()
    if not self.m_model.endAwardInfoData then
        for i = 1, 5 do
            local awardParNode = self:findGameObject("awardNode"..i)
            local awardItemLua =UIUtil.findLuaBehaviour(awardParNode)
            LuaBehaviourUtil.setObjectVisible(awardItemLua, "ItemNode", false)
        end
        return
    end
    local awardInfos = self.m_model.endAwardInfoData.awardInfos
    for index = 1, 5 do
        local curAwardData = awardInfos[index]
        local awardParNode = self:findGameObject("awardNode"..index)
        local awardItemLua =UIUtil.findLuaBehaviour(awardParNode)
        local awardItemNode = awardItemLua:FindGameObject("ItemNode")
        local isExist = curAwardData ~= nil
        LuaBehaviourUtil.setObjectVisible(awardItemLua, "ItemNode", isExist)
        if isExist then
            local awardType = curAwardData.awardType
            LuaBehaviourUtil.setObjectVisible(awardItemLua, "img_awardHintImg", awardType ~= 1)
            local hintName = (awardType == 2) and "simulateLeft_text_0061" or "simulateLeft_text_0062"
            LuaBehaviourUtil.setTextByLanKey(awardItemLua, "text_awardHintText", hintName)
            GameUtil:updateItemElementByData(awardItemNode, curAwardData.awardData, true, true)
        end
    end
    RewardUtil:rewardTipsByRewards(self.m_model.endAwardInfoData.serverAwardInfos)
end

function M:refreshSelectNode()
    self:setLeftInfo(false)
    local talentXlsxData = ConfigManager:getCfgByName("reopen_talent")
    local allTalentData = self.m_model.m_talent
    local talentValues = self.m_model.m_talentValues
    local qualityColourValues = self.m_model.m_qualityColourValues
    local normalName = "a_hd_jhmnq_tfjc_xuanxiang_lv"
    local selectTalentNode = self:findGameObject("selectTalentNode")
    local selectTalentNodeLua = UIUtil.findLuaBehaviour(selectTalentNode)
    for index = 1, 10 do
        local itemTalentId = allTalentData[index] 
        local itemXlsxData = talentXlsxData[itemTalentId]
        if itemXlsxData then
            local itemNode = selectTalentNodeLua:FindGameObject("itemNode_"..index)
            local itemNodeLuaBehaviour = UIUtil.findLuaBehaviour(itemNode)
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_name", itemXlsxData.name)
            local text_nameNode = itemNodeLuaBehaviour:FindText("text_name")
            local curQualityColour = qualityColourValues[itemXlsxData.quality]
            text_nameNode.color = Color(curQualityColour[1], curQualityColour[2],  curQualityColour[3])
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_info", itemXlsxData.description)
            LuaBehaviourUtil.setImg(itemNodeLuaBehaviour, "itemBg",talentValues[itemXlsxData.quality] or normalName,  "pub_ui")
        end
    end
end

