function M:setSelectBtnEvents()
    local selectTalentNode = self:findGameObject("selectTalentNode")
    local selectTalentNodeLua = UIUtil.findLuaBehaviour(selectTalentNode)
    for index = 1, 10 do
        local itemNode = selectTalentNodeLua:FindGameObject("itemNode_"..index)
        local itemNodeLuaBehaviour = UIUtil.findLuaBehaviour(itemNode)
        local selectBtn = itemNodeLuaBehaviour:FindGameObject("btn_itemBg")
        if not IsNull(selectBtn) then
            UIUtil.setButtonClick(
                    selectBtn.transform,
                    function()
                        audio:SendEvtUI("UI_Tab_N3")
                        local isShow = self.m_model:modifySelectCount(index)
                        LuaBehaviourUtil.setObjectVisible(itemNodeLuaBehaviour, "img_selectImg", isShow)
                    end
            )
        end
    end
end

function M:setSpine()
    local configHeros = ConfigManager:getCommonValueById(691) or {{101,501,1}}
    local configScaleHeros = ConfigManager:getCommonValueById(692) or {1}
    local randomIndex = math.random(1, table.nums(configHeros))
    local heroDatas = configHeros[randomIndex]
    local scaleConfig = configScaleHeros[randomIndex]
    if heroDatas then
        local reward_data = RewardUtil:getProcessRewardData(heroDatas)
        if reward_data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROS or reward_data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROSEXT then
            local cfg = UserDataManager.hero_data:getHeroConfigByCid(reward_data.data_id)
            if cfg then
                local icon = cfg.hero_spine
                if self.cacheSpineName == icon then
                    return
                else
                    self.cacheSpineName = icon
                end

            end
        elseif reward_data.data_type == RewardUtil.REWARD_TYPE_KEYS.HERO_SKIN then
            local cur_skin_cfg = ConfigManager:getHeroSkinCfg(reward_data.data_id)
            local icon = cur_skin_cfg.hero_spine
            if self.cacheSpineName == icon then
                return
            else
                self.cacheSpineName = icon
            end
        end
        for index = 1, 4 do
            local hero_spineObj = self:findGameObject("hero_spine"..index)
            GameUtil:updateSpineLoadSet(hero_spineObj, "RoleSpine/" .. self.cacheSpineName, "idle", 0, true)
            UIUtil.setScale(hero_spineObj.transform, scaleConfig)
        end
    end
end

function M:destroy()
    M.super.destroy(self)
end

return M
